#!/usr/bin/env node
/**
 * Writes api/_lib/content-dates.ts: one `lastmod` date per content dataset, used by api/sitemap.ts.
 * The date is the day of the last commit that touched any of the dataset's data files
 * (`git log -1 --format=%cs -- <file>`), i.e. the last meaningful content change, not the day of a deploy.
 * A dataset whose files have no commit yet (new files) gets `null` and its URLs are listed without <lastmod>.
 *
 * Run it locally with full git history after content changes, then commit the generated file:
 *   node scripts/content-dates.mjs
 * (A shallow clone, like Vercel's build checkout, cannot know older dates, so this is not run at build time.)
 */
import { execFileSync } from 'node:child_process';
import { existsSync, writeFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const root = join(dirname(fileURLToPath(import.meta.url)), '..');
const L = (n) => `api/_lib/${n}.ts`;

/** dataset key -> files whose content defines the pages of that family */
export const DATASETS = {
  task2: [L('data-task2'), L('data-task2-more'), L('data-task2-new')],
  task1: [L('data-task1')],
  speakingPart1: [L('data-part1'), L('data-part1-more'), L('data-part1-new')],
  speakingPart2: [L('data-part2'), L('data-part2-more'), L('data-part2-new')],
  speakingPart3: [L('data-part3'), L('data-part3-new')],
  vocabulary: [L('data-vocab'), L('data-vocab-new')],
  course: [L('data-course')],
  learnGuides: [L('data-learn-guides'), L('data-learn-guides-a'), L('data-learn-guides-b')],
  learnWords: [L('data-learn-words'), L('data-learn-words-a'), L('data-learn-words-b')],
  writingTask1Guide: ['public/ielts-writing-task-1.html'],
  writingTask2Guide: ['public/ielts-writing-task-2.html'],
  speakingPracticeGuide: ['public/ielts-speaking-practice.html'],
  ieltsHub: [L('ielts-hub')],
  englishLanding: [L('en-landing')],
};

const git = (...args) => execFileSync('git', args, { cwd: root, encoding: 'utf8' }).trim();
const shallow = git('rev-parse', '--is-shallow-repository') === 'true';

const dates = {};
const dirty = [];
for (const [key, files] of Object.entries(DATASETS)) {
  let latest = null;
  for (const f of files) {
    if (!existsSync(join(root, f))) continue;
    const d = git('log', '-1', '--format=%cs', '--', f);
    if (d && (!latest || d > latest)) latest = d;
    if (git('status', '--porcelain', '--', f)) dirty.push(f);
  }
  dates[key] = latest;
}

const out = `// Generated by scripts/content-dates.mjs (node scripts/content-dates.mjs). Do not edit by hand.
// One date per content dataset: the day of the last commit that changed any of its data files.
// null = no commit yet, so the sitemap lists those URLs without <lastmod>.
export const CONTENT_DATES = ${JSON.stringify(dates, null, 2)} as const satisfies Record<string, string | null>;

export type ContentDateKey = keyof typeof CONTENT_DATES;
export const contentDate = (key: ContentDateKey): string | undefined => CONTENT_DATES[key] ?? undefined;
`;
writeFileSync(join(root, 'api/_lib/content-dates.ts'), out);
console.log(out);
if (shallow) console.warn('WARNING: shallow clone. Dates older than the shallow boundary show the boundary commit date. Re-run with full history before committing.');
if (dirty.length) console.warn(`WARNING: uncommitted changes in ${dirty.join(', ')}. Their dates show the last COMMITTED change; re-run after committing.`);
